select id, supplier_name, country, city, rating, max(rating) over (partition by city order by rating, id rows between unbounded preceding and current row) as running_max_rating, count(rating) over (partition by city order by rating, id rows between unbounded preceding and current row) as running_count_rating, min(rating) over (partition by city order by rating, id rows between unbounded preceding and current row) as running_min_rating from suppliers;
